import neverkickoff.Device;
import neverkickoff.DeviceException;
import neverkickoff.Engine;
import neverkickoff.Hotkeys;
import neverkickoff.Json;
import neverkickoff.Key;
import neverkickoff.Keys;
import neverkickoff.Spec;
import neverkickoff.Window;
import neverkickoff.Ydotool;

import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Cross-language contract.
 *
 * Every case in tests/fixtures/contract.json was generated by the Python
 * implementation, which stays the source of truth. If this fails, the Java port
 * has drifted from Python - not the other way around.
 *
 *     java -cp build/classes:build/test-classes ContractTest
 */
public final class ContractTest {
    private ContractTest() {}

    private static final List<String> FAILURES = new ArrayList<>();

    public static void main(String[] args) {
        Object fixture = Json.parse(read(readFixturePath()));

        checkNormalizeSteps(fixture);
        checkParseCombo(fixture);
        checkLoadSpec(fixture);
        checkFormatHotkey(fixture);
        checkAsText(fixture);
        checkKeycode(fixture);
        checkEngine(fixture);

        if (!FAILURES.isEmpty()) {
            System.out.println("Java drifted from the Python contract:");
            for (String failure : FAILURES) {
                System.out.println("  " + failure);
            }
            System.out.println(FAILURES.size() + " failure(s)");
            System.exit(1);
        }
        System.out.println("all passed");
    }

    private static void checkNormalizeSteps(Object fixture) {
        List<Object> cases = list(fixture, "normalize_steps");
        for (int i = 0; i < cases.size(); i++) {
            Map<String, Object> testCase = map(cases.get(i));
            check("normalize_steps[" + i + "]", Spec.normalizeSteps(testCase.get("spec")), testCase.get("expect"));
        }
    }

    private static void checkParseCombo(Object fixture) {
        List<Object> cases = list(fixture, "parse_combo");
        for (int i = 0; i < cases.size(); i++) {
            Map<String, Object> testCase = map(cases.get(i));
            Object value = null;
            Object error = null;
            try {
                List<Object> keys = new ArrayList<>();
                for (Key key : Keys.parseComboValue(testCase.get("combo"))) {
                    keys.add(key.toJson());
                }
                value = keys;
            } catch (Keys.KeyError failure) {
                error = failure.getMessage();
            }
            check("parse_combo[" + i + "] keys", value, testCase.get("expect"));
            check("parse_combo[" + i + "] error", error, testCase.get("error"));
        }
    }

    private static void checkLoadSpec(Object fixture) {
        List<Object> cases = list(fixture, "load_spec");
        for (int i = 0; i < cases.size(); i++) {
            Map<String, Object> testCase = map(cases.get(i));
            Object value = null;
            Object error = null;
            try {
                value = Spec.loadSpec(testCase.get("click"));
            } catch (Keys.KeyError failure) {
                error = failure.getMessage();
            }
            check("load_spec[" + i + "] spec", value, testCase.get("expect"));
            check("load_spec[" + i + "] error", error, testCase.get("error"));
        }
    }

    private static void checkFormatHotkey(Object fixture) {
        List<Object> cases = list(fixture, "format_hotkey");
        for (int i = 0; i < cases.size(); i++) {
            Map<String, Object> testCase = map(cases.get(i));
            String keysym = (String) testCase.get("keysym");
            int state = number(testCase.get("state")).intValue();
            check("format_hotkey[" + i + "]", Hotkeys.formatHotkey(keysym, state), testCase.get("expect"));
        }
    }

    private static void checkAsText(Object fixture) {
        List<Object> cases = list(fixture, "as_text");
        for (int i = 0; i < cases.size(); i++) {
            Map<String, Object> testCase = map(cases.get(i));
            Map<String, Object> value = map(testCase.get("value"));
            String kind = (String) value.get("kind");
            Object raw = null;
            if ("bytes".equals(kind)) {
                List<Object> data = list(value, "data");
                byte[] bytes = new byte[data.size()];
                for (int b = 0; b < data.size(); b++) {
                    bytes[b] = (byte) number(data.get(b)).intValue();
                }
                raw = bytes;
            } else if ("str".equals(kind)) {
                raw = value.get("data");
            }
            check("as_text[" + i + "]", Window.asText(raw), testCase.get("expect"));
        }
    }

    private static void checkKeycode(Object fixture) {
        List<Object> cases = list(fixture, "keycode");
        for (int i = 0; i < cases.size(); i++) {
            Map<String, Object> testCase = map(cases.get(i));
            Key key = Key.fromJson(testCase.get("key"));
            Long value = null;
            Object error = null;
            try {
                value = (long) Ydotool.keycode(key);
            } catch (RuntimeException failure) {
                error = "ValueError";
            }
            check("keycode[" + i + "] value", value, testCase.get("expect"));
            check("keycode[" + i + "] error", error, testCase.get("error_kind"));
        }
    }

    private static void checkEngine(Object fixture) {
        List<Object> cases = list(fixture, "engine");
        for (int i = 0; i < cases.size(); i++) {
            Map<String, Object> testCase = map(cases.get(i));
            Object spec = testCase.get("spec");
            Object focusedRaw = testCase.get("focused");
            String focused = focusedRaw instanceof String ? (String) focusedRaw : null;
            Object failOnRaw = testCase.get("fail_on");
            Long failOn = failOnRaw instanceof Number ? ((Number) failOnRaw).longValue() : null;

            Recorder device = new Recorder(failOn);
            Engine<Recorder> engine = new Engine<>(device, () -> focused);
            Long fired = null;
            Object error = null;
            try {
                fired = engine.run(spec);
            } catch (RuntimeException failure) {
                error = "RuntimeError";
            }
            check("engine[" + i + "] events", device.events, testCase.get("expect_events"));
            check("engine[" + i + "] fired", fired, testCase.get("expect_fired"));
            check("engine[" + i + "] error", error, testCase.get("expect_error_kind"));
        }
    }

    private static void check(String label, Object actual, Object expected) {
        if (!Json.deepEquals(actual, expected)) {
            FAILURES.add(label + "\n    java     " + Json.stringify(actual)
                    + "\n    contract " + Json.stringify(expected));
        }
    }

    /** Records every call, and fails on the Nth key press like the Python Recorder. */
    static final class Recorder implements Device {
        final List<Object> events = new ArrayList<>();
        private final Long failOn;
        private long presses;

        Recorder(Long failOn) {
            this.failOn = failOn;
        }

        private void record(String kind, String token) {
            events.add(List.of(kind, token));
        }

        @Override
        public void mousePress(String button) {
            record("mouse_press", button);
        }

        @Override
        public void mouseRelease(String button) {
            record("mouse_release", button);
        }

        @Override
        public void keyPress(Key key) {
            if (failOn != null) {
                presses++;
                if (presses == failOn) {
                    throw new DeviceException("device failure");
                }
            }
            record("key_press", key.token());
        }

        @Override
        public void keyRelease(Key key) {
            record("key_release", key.token());
        }
    }

    /**
     * The fixture is the repo's tests/fixtures/contract.json, resolved relative
     * to this java/ directory rather than the current working directory.
     */
    private static Path readFixturePath() {
        String override = System.getProperty("neverkickoff.contract");
        if (override != null) {
            return Paths.get(override);
        }
        try {
            URL location = ContractTest.class.getProtectionDomain().getCodeSource().getLocation();
            Path classes = Paths.get(location.toURI());
            // classes = <repo>/java/build/test-classes
            Path javaDir = classes.getParent().getParent();
            return javaDir.resolve("..").resolve("tests").resolve("fixtures").resolve("contract.json").normalize();
        } catch (Exception error) {
            throw new RuntimeException("cannot locate contract.json", error);
        }
    }

    private static String read(Path path) {
        try {
            return new String(Files.readAllBytes(path), StandardCharsets.UTF_8);
        } catch (Exception error) {
            throw new RuntimeException("cannot read " + path + ": " + error.getMessage(), error);
        }
    }

    @SuppressWarnings("unchecked")
    private static List<Object> list(Object source, String key) {
        Object value = map(source).get(key);
        if (!(value instanceof List)) {
            throw new IllegalStateException("fixture section '" + key + "' is not a list");
        }
        return (List<Object>) value;
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> map(Object value) {
        if (!(value instanceof Map)) {
            throw new IllegalStateException("expected an object, got " + value);
        }
        return (Map<String, Object>) value;
    }

    private static Number number(Object value) {
        if (!(value instanceof Number)) {
            throw new IllegalStateException("expected a number, got " + value);
        }
        return (Number) value;
    }
}
